class UserDto {
  // final: Khởi tạo một lần tại runtime, cố định tham chiếu bất biến
  final String id;
  final String email;

  UserDto({required this.id, required this.email});

  void demonstrateTypes(Map<String, dynamic> json) {
    // 1. var: Type inference tại compile-time -> kiểu int tĩnh
    var parsedAge = json['age'] as int? ?? 18;
    // parsedAge = '19'; // Lỗi biên dịch: A value of type 'String' can't be assigned to 'int'

    // 2. dynamic: Bỏ qua static checking, resolve method lúc runtime
    dynamic untypedData = json['metadata'];
    try {
      // Rủi ro NoSuchMethodError nếu payload thực tế không có phương thức này
      untypedData.nonExistentMethod();
    } on NoSuchMethodError catch (e) {
      // Production best practice: Tránh dynamic, ưu tiên Object? + type narrowing
      print('Caught runtime dynamic dispatch failure: $e');
    }

    // 3. Type-safe narrowing thay thế dynamic:
    final Object? rawPayload = json['payload'];
    if (rawPayload is String) {
      print('Safe string length: ${rawPayload.length}');
    }
  }
}

