// Model an toàn tuyệt đối với Sound Null Safety trong Dart 3
class AccountSession {
  // 1. Non-nullable: Compiler cam kết biến này không bao giờ là null
  final String token;
  final DateTime expiresAt;

  // 2. Nullable: Có thể mang giá trị null, bắt buộc xử lý trước khi truy cập
  final String? refreshToken;

  const AccountSession({
    required this.token,
    required this.expiresAt,
    this.refreshToken,
  });

  bool isExpired() {
    return DateTime.now().isAfter(expiresAt);
  }

  String getSecureHeader() {
    // Sound Flow Analysis: Dart nhận biết refreshToken có thể null
    // Dùng pattern matching hoặc null coalescing an toàn
    final activeToken = refreshToken ?? token;
    return 'Bearer $activeToken';
  }
}

