class ProfileManager {
  String? _cachedAvatarUrl;

  // ❌ Antipattern: Dùng ! tiềm ẩn crash runtime nếu có race condition
  String getAvatarUnsafe() {
    return _cachedAvatarUrl!; // Ném TypeError nếu _cachedAvatarUrl == null
  }

  // ✅ Senior Approach 1: Local variable shadowing kích hoạt Type Promotion
  String getAvatarSafe() {
    final avatar = _cachedAvatarUrl;
    if (avatar != null) {
      // Compiler tự động promote 'avatar' từ 'String?' thành 'String'
      return avatar.toUpperCase();
    }
    return 'https://cdn.app.com/default-avatar.png';
  }

  // ✅ Senior Approach 2: Dart 3 pattern matching (if-case)
  String formatAvatarWithPattern() {
    if (_cachedAvatarUrl case final url?) {
      return 'User URL: $url';
    }
    return 'No avatar found';
  }
}

