class ClientConfig {
  String? host;
  int? port;
  Map<String, String>? headers;

  void configure(ClientConfig? source) {
    // Ví dụ 1: Safe navigation (?.) & Null-aware index (?[])
    // Nếu source null hoặc headers null -> trả về null an toàn
    final String? authHeader = source?.headers?['Authorization'];

    // Ví dụ 2: Null coalescing (??) cung cấp giá trị mặc định dự phòng
    final String effectiveHost = source?.host ?? 'https://api.internal.com';
    final int effectivePort = source?.port ?? 443;

    // Ví dụ 3: Null-aware assignment (??=) chỉ gán nếu biến đang là null
    headers ??= <String, String>{};
    headers!['Host'] = '$effectiveHost:$effectivePort';
    if (authHeader != null) {
      headers!['Authorization'] = authHeader;
    }
  }
}

