import 'dart:collection';

class Product {
  final String sku;
  final String name;

  const Product({required this.sku, required this.name});

  // Bắt buộc override cả == và hashCode để Set/Map hoạt động chính xác
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Product && runtimeType == other.runtimeType && sku == other.sku;

  @override
  int get hashCode => sku.hashCode;
}

void runCollectionDemo() {
  final p1 = Product(sku: 'A01', name: 'MacBook');
  final p2 = Product(sku: 'A01', name: 'MacBook Pro'); // Cùng SKU

  // 1. List: Giữ nguyên thứ tự, cho phép duplicate (Length: 2)
  final List<Product> list = [p1, p2];

  // 2. Set: Tự động deduplicate theo hashCode & operator == (Length: 1)
  final Set<Product> uniqueSet = {p1, p2};

  // 3. Map: Tra cứu O(1) theo Key duy nhất
  final Map<String, Product> catalog = {p1.sku: p1};

  // Bảo vệ tính toàn vẹn trạng thái (Immutability pattern)
  final readOnlyList = UnmodifiableListView(list);
  // readOnlyList.add(p1); // Ném UnsupportedError lúc runtime
}

