import 'dart:async';

class DataTracker {
  // 1. Future: Thao tác 1 lần duy nhất (One-shot execution)
  Future<String> fetchUserToken() async {
    await Future.delayed(const Duration(milliseconds: 100));
    return 'auth_token_xyz_999';
  }

  // 2. Stream: Chuỗi nhiều sự kiện theo thời gian
  final StreamController<int> _counterController = StreamController<int>.broadcast();
  Stream<int> get counterStream => _counterController.stream;

  void emitTick(int value) {
    if (!_counterController.isClosed) {
      _counterController.add(value);
    }
  }

  // Bắt buộc dọn dẹp tài nguyên tránh rò rỉ bộ nhớ
  void dispose() {
    _counterController.close();
  }
}

// Trong UI Widget: Quản lý vòng đời StreamSubscription
void bindSubscription(DataTracker tracker) {
  final StreamSubscription<int> sub = tracker.counterStream.listen(
    (val) => print('Received tick: $val'),
    onError: (err) => print('Stream error: $err'),
    cancelOnError: false,
  );

  // Khi widget bị unmount: sub.cancel();
}

