import 'dart:async';

void demonstrateEventLoop() async {
  print('1: Synchronous start'); // Chạy ngay lập tức trên callstack

  scheduleMicrotask(() {
    print('2: Microtask executed'); // Ưu tiên cao hơn Event Queue
  });

  // await đẩy continuation vào hàng đợi sau khi Timer xong
  await Future.delayed(Duration.zero, () {
    print('3: Event Queue item processed');
  });

  print('4: Continuation resumed after await'); // Chạy sau khi Future hoàn tất
}

// Output theo thứ tự Event Loop:
// 1: Synchronous start
// 2: Microtask executed
// 3: Event Queue item processed
// 4: Continuation resumed after await

