sealed class ViewState {}
class LoadingState extends ViewState {}
class SuccessState extends ViewState {
  final String payload;
  SuccessState(this.payload);
}

class UIController {
  ViewState? _state;

  void renderUI() {
    // 1. Shadowing ra biến local để kích hoạt Flow Analysis an toàn 100%
    final state = _state;

    if (state == null) {
      print('Render Idle view');
      return;
    }

    // 2. Type Promotion qua toán tử `is`
    if (state is SuccessState) {
      // Compiler tự động promote 'state' từ 'ViewState' sang 'SuccessState'
      // Không cần ép kiểu: (state as SuccessState).payload
      print('Success payload: ${state.payload}');
    } else if (state is LoadingState) {
      print('Show loading indicator');
    }
  }
}

