void sendMoney(String recipient, double amount, [String? note]) {
  print('Sending $amount to $recipient with note: $note');
}

// 2. Named: Rõ ràng, dễ đọc, chuẩn idiomatic Flutter Widget API
class AppPrimaryButton {
  final String title;
  final VoidCallback onPressed;
  final bool isLoading;
  final double borderRadius;

  const AppPrimaryButton({
    required this.title,       // Bắt buộc truyền tên
    required this.onPressed,
    this.isLoading = false,    // Giá trị mặc định
    this.borderRadius = 8.0,
  });
}

void usage() {
  // Positional call: Phải nhớ đúng thứ tự
  sendMoney('Alice', 500.0, 'Lunch fee');

  // Named call: Thứ tự linh hoạt, code tự giải thích ý nghĩa tham số
  final btn = AppPrimaryButton(
    isLoading: true,
    title: 'Confirm Payment',
    onPressed: () => print('Submitted'),
  );
}

