ValueGetter<int> createCounter(int initialValue) {
  int count = initialValue; // Biến nằm trong scope của createCounter
  return () {
    count += 1; // Capture và duy trì biến count trong heap
    return count;
  };
}

class LeakTrapExample {
  final String largeDataPayload = '20MB cached bytes';

  void registerCallback(ChangeNotifier globalEventHub) {
    // ❌ RỦI RO MEMORY LEAK: Closure ẩn danh capture ngầm tham chiếu 'this'
    globalEventHub.addListener(() {
      print('Event received for payload: $largeDataPayload');
    });
    // Nếu không removeListener, LeakTrapExample vĩnh viễn không được GC thu gom!
  }

  // ✅ Tối ưu: Sử dụng tear-off khi chữ ký hàm tương đồng
  void handleTap() {
    print('Button tapped');
  }

  VoidCallback get onAction => handleTap; // Tear-off trực tiếp
}

