    with MetricsTracker     // with: Tái sử dụng logic của MetricsTracker
    implements Cacheable {  // implements: Bắt buộc hiện thực lại hợp đồng clearCache

  @override
  void clearCache() {
    print('Clearing memory cache for users');
  }

  void fetchUser(String id) {
    connect(); // Kế thừa từ BaseRepository qua 'extends'
    logMetric('fetch_user_$id'); // Tái sử dụng từ mixin qua 'with'
  }
}

