import 'package:flutter/material.dart';

// 1. StatelessWidget: Thuần túy phụ thuộc input, không có internal state
class UserHeaderCard extends StatelessWidget {
  final String userName;
  final String role;

  const UserHeaderCard({
    super.key,
    required this.userName,
    required this.role,
  });

  @override
  Widget build(BuildContext context) {
    return Card(
      child: ListTile(
        title: Text(userName),
        subtitle: Text(role),
      ),
    );
  }
}

// 2. StatefulWidget: Lưu giữ mutable state (TextEditingController, Animation)
class DynamicSearchInput extends StatefulWidget {
  final ValueChanged<String> onSearchSubmitted;

  const DynamicSearchInput({super.key, required this.onSearchSubmitted});

  @override
  State<DynamicSearchInput> createState() => _DynamicSearchInputState();
}

class _DynamicSearchInputState extends State<DynamicSearchInput> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController();
  }

  @override
  void dispose() {
    _controller.dispose(); // Bắt buộc dọn dẹp để tránh leak bộ nhớ native
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: _controller,
      onSubmitted: widget.onSearchSubmitted,
    );
  }
}

