import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';

// Minh chứng thực tế về cách một Widget tạo ra Element và RenderObject
class CustomColorBox extends LeafRenderObjectWidget {
  final Color color;
  final double size;

  const CustomColorBox({
    super.key,
    required this.color,
    required this.size,
  });

  // 1. Tạo Element (Cột sống điều phối)
  @override
  LeafRenderObjectElement createElement() => LeafRenderObjectElement(this);

  // 2. Tạo RenderObject (Thực thi tính toán layout & paint)
  @override
  RenderColorBox createRenderObject(BuildContext context) =>
      RenderColorBox(color: color, size: size);

  // 3. Tối ưu: Chỉ cập nhật thuộc tính xuống RenderObject cũ khi widget rebuild
  @override
  void updateRenderObject(BuildContext context, RenderColorBox renderObject) {
    renderObject
      ..boxColor = color
      ..boxSize = size;
  }
}

class RenderColorBox extends RenderBox {
  Color _color;
  double _size;

  RenderColorBox({required Color color, required double size})
      : _color = color,
        _size = size;

  set boxColor(Color val) {
    if (_color == val) return;
    _color = val;
    markNeedsPaint(); // Đánh dấu dirty paint mà không cần relayout
  }

  set boxSize(Double val) {
    if (_size == val) return;
    _size = val;
    markNeedsLayout(); // Đánh dấu dirty layout
  }

  @override
  void performLayout() {
    // Quy tắc: Constraints go down, Sizes go up
    size = constraints.constrain(Size(_size, _size));
  }

  @override
  void paint(PaintingContext context, Offset offset) {
    final paint = Paint()..color = _color;
    context.canvas.drawRect(offset & size, paint);
  }
}

