class TodoItem {
  final String id;
  final String taskName;
  const TodoItem({required this.id, required this.taskName});
}

class TodoListView extends StatefulWidget {
  final List<TodoItem> items;
  const TodoListView({super.key, required this.items});

  @override
  State<TodoListView> createState() => _TodoListViewState();
}

class _TodoListViewState extends State<TodoListView> {
  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      itemCount: widget.items.length,
      itemBuilder: (context, index) {
        final item = widget.items[index];
        // 🛡️ BẮT BUỘC: Sử dụng ValueKey dựa trên ID nghiệp vụ duy nhất
        // Giúp Element Tree map chính xác State khi item bị xóa hoặc tráo vị trí
        return Dismissible(
          key: ValueKey(item.id),
          onDismissed: (_) => widget.items.removeAt(index),
          child: TodoRowWidget(
            key: ValueKey(item.id), // Đảm bảo state không bị nhảy sang row khác
            item: item,
          ),
        );
      },
    );
  }
}

class TodoRowWidget extends StatefulWidget {
  final TodoItem item;
  const TodoRowWidget({super.key, required this.item});

