import 'package:flutter/material.dart';

class LifecycleDemoWidget extends StatefulWidget {
  final String userId;
  const LifecycleDemoWidget({super.key, required this.userId});

  @override
  State<LifecycleDemoWidget> createState() => _LifecycleDemoWidgetState();
}

class _LifecycleDemoWidgetState extends State<LifecycleDemoWidget> {
  late final ScrollController _scrollController;

  @override
  void initState() {
    super.initState();
    // 1. Khởi tạo một lần duy nhất, không dùng context để đọc InheritedWidget ở đây
    _scrollController = ScrollController();
    print('initState: Controller initialized');
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // 2. An toàn để đọc InheritedWidget (Theme, MediaQuery, Provider)
    final isDark = Theme.of(context).brightness == Brightness.dark;
    print('didChangeDependencies: Theme isDark = $isDark');
  }

  @override
  void didUpdateWidget(covariant LifecycleDemoWidget oldWidget) {
    super.didUpdateWidget(oldWidget);
    // 3. Xử lý khi widget cha rebuild truyền vào prop mới
    if (widget.userId != oldWidget.userId) {
      print('didUpdateWidget: userId changed from ${oldWidget.userId} to ${widget.userId}');
    }
  }

  @override
  Widget build(BuildContext context) {
    // 4. Sinh ra Widget blueprint
    return ListView(controller: _scrollController, children: [Text(widget.userId)]);
  }

  @override
  void dispose() {
    // 5. Giải phóng tài nguyên dứt điểm
    _scrollController.dispose();
    super.dispose();
  }
}

