import 'package:flutter/foundation.dart';

// 1. State Model: Bất biến (Immutable) đại diện cho trạng thái giỏ hàng
@immutable
class CartState {
  final List<String> itemIds;
  final bool isCheckingOut;

  const CartState({this.itemIds = const [], this.isCheckingOut = false});

  int get totalItems => itemIds.length;

  CartState copyWith({List<String>? itemIds, bool? isCheckingOut}) {
    return CartState(
      itemIds: itemIds ?? this.itemIds,
      isCheckingOut: isCheckingOut ?? this.isCheckingOut,
    );
  }
}

// 2. Single Source of Truth: Quản lý luồng dữ liệu một chiều (Unidirectional Data Flow)
class CartNotifier extends ValueNotifier<CartState> {
  CartNotifier() : super(const CartState());

  void addItem(String id) {
    // UI phát Action -> Notifier mutate state -> Thông báo người nghe
    value = value.copyWith(itemIds: [...value.itemIds, id]);
  }
}

