class SessionManager extends ChangeNotifier {
  bool _isDisposed = false;
  String? _currentUserToken;

  String? get token => _currentUserToken;

  void updateToken(String newToken) {
    if (_currentUserToken == newToken) return; // Tránh notify dư thừa
    _currentUserToken = newToken;

    // 🛡️ Kiểm tra cờ an toàn trước khi gọi notifyListeners
    if (!_isDisposed) {
      notifyListeners();
    }
  }

  @override
  void dispose() {
    _isDisposed = true;
    super.dispose();
  }
}

