void setupLocator() {
  // 1. Lazy singleton: Khởi tạo khi có request đầu tiên
  sl.registerLazySingleton<SecureStorageService>(() => SecureStorageServiceImpl());

  // 2. Factory: Khởi tạo instance mới mỗi lần gọi
  sl.registerFactory<AuthRepository>(() => AuthRepository(sl<SecureStorageService>()));
}

void runModule() {
  // Truy cập bất kỳ đâu mà không cần BuildContext
  final authRepo = sl<AuthRepository>();
}

