import 'package:mocktail/mocktail.dart';

// Khai báo mock
abstract class UserRepository {
  Future<String> getUserName();
}
class MockUserRepository extends Mock implements UserRepository {}

// Giả lập Cubit cần test
class UserCubit extends BlocBase<String> {
  final UserRepository repo;
  UserCubit(this.repo) : super('Initial');

  Future<void> loadUser() async {
    emit('Loading');
    try {
      final name = await repo.getUserName();
      emit(name);
    } catch (_) {
      emit('Error');
    }
  }
}

void main() {
  late MockUserRepository mockRepo;

  setUp(() => mockRepo = MockUserRepository());

  // ✅ Kiểm thử State Flow hoàn chỉnh với bloc_test
  blocTest<UserCubit, String>(
    'Phát ra [Loading, Alex] khi loadUser thành công',
    build: () {
      when(() => mockRepo.getUserName()).thenAnswer((_) async => 'Alex');
      return UserCubit(mockRepo);
    },
    act: (cubit) => cubit.loadUser(),
    expect: () => <String>['Loading', 'Alex'],
    verify: (_) => verify(() => mockRepo.getUserName()).called(1),
  );
}

