import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

// 1. Quản lý trạng thái xác thực kế thừa ChangeNotifier
class AuthStateNotifier extends ChangeNotifier {
  bool _isLoggedIn = false;
  bool get isLoggedIn => _isLoggedIn;

  void login() {
    _isLoggedIn = true;
    notifyListeners(); // Kích hoạt refreshListenable của GoRouter
  }

  void logout() {
    _isLoggedIn = false;
    notifyListeners();
  }
}

// 2. Cấu hình GoRouter phản ứng tự động theo AuthStateNotifier
GoRouter createReactiveRouter(AuthStateNotifier authNotifier) {
  return GoRouter(
    initialLocation: '/dashboard',
    // 🛡️ BẮT BUỘC: Đăng ký lắng nghe thay đổi trạng thái
    refreshListenable: authNotifier,
    redirect: (context, state) {
      final loggedIn = authNotifier.isLoggedIn;
      final isLoggingIn = state.matchedLocation == '/login';

      // Nếu chưa login và không ở trang login -> ép về /login
      if (!loggedIn && !isLoggingIn) return '/login';

      // Nếu đã login mà vẫn đang đứng ở /login -> đưa vào /dashboard
      if (loggedIn && isLoggingIn) return '/dashboard';

      return null; // Giữ nguyên vị trí hiện tại
    },
    routes: [
      GoRoute(path: '/login', builder: (_, __) => const Scaffold(body: Text('Login'))),
      GoRoute(path: '/dashboard', builder: (_, __) => const Scaffold(body: Text('Dashboard'))),
    ],
  );
}

