import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

class UserSession {
  final bool isAuthenticated;
  final String role; // 'user' | 'admin'
  const UserSession({required this.isAuthenticated, required this.role});
}

GoRouter buildSecureRouter(UserSession session) {
  return GoRouter(
    initialLocation: '/admin/dashboard',
    redirect: (context, state) {
      final targetPath = state.matchedLocation;

      // 1. Kiểm tra xác thực cơ bản
      if (!session.isAuthenticated) {
        // Lưu lại target path vào query param để redirect sau khi login thành công
        return targetPath == '/login' ? null : '/login?from=${Uri.encodeComponent(targetPath)}';
      }

      // 2. Role-Based Access Control (RBAC): Chỉ admin mới được vào /admin/*
      if (targetPath.startsWith('/admin') && session.role != 'admin') {
        return '/forbidden'; // Trang 403 không có quyền
      }

      return null; // Hợp lệ, cho phép đi tiếp
    },
    routes: [
      GoRoute(path: '/login', builder: (_, __) => const Scaffold(body: Text('Login Page'))),
      GoRoute(path: '/forbidden', builder: (_, __) => const Scaffold(body: Text('403 Forbidden'))),
      GoRoute(path: '/admin/dashboard', builder: (_, __) => const Scaffold(body: Text('Admin Portal'))),
    ],
  );
}

