abstract class ArticleRemoteDataSource {
  Future<List<String>> fetchArticlesFromApi();
}

abstract class ArticleLocalDataSource {
  Future<List<String>> getCachedArticles();
  Future<void> saveArticles(List<String> articles);
}

// Repository điều phối thông minh giữa Remote và Local Cache
class ArticleRepositoryImpl {
  final ArticleRemoteDataSource remoteSource;
  final ArticleLocalDataSource localSource;

  ArticleRepositoryImpl({
    required this.remoteSource,
    required this.localSource,
  });

  Future<List<String>> getArticles({bool forceRefresh = false}) async {
    if (!forceRefresh) {
      final cached = await localSource.getCachedArticles();
      if (cached.isNotEmpty) return cached; // Trả về cache ngay lập tức
    }

    try {
      final freshData = await remoteSource.fetchArticlesFromApi();
      await localSource.saveArticles(freshData); // Đồng bộ vào local storage
      return freshData;
    } catch (e) {
      // Fallback về cache khi mất kết nối mạng
      final fallback = await localSource.getCachedArticles();
      if (fallback.isNotEmpty) return fallback;
      rethrow;
    }
  }
}

