class DatabaseClient {
  DatabaseClient._internal(); // Private constructor ngăn tạo instance tự do từ bên ngoài

  static final DatabaseClient _instance = DatabaseClient._internal();

  // Factory constructor luôn trả về duy nhất một instance tĩnh
