}

// 2. Factory Pattern trả về các Subclass đa hình (Polymorphic Factory)
abstract class PlatformButton {
  void render();

  factory PlatformButton(String platform) {
    if (platform == 'ios') return _CupertinoButton();
    return _MaterialButton();
  }
}

class _MaterialButton implements PlatformButton {
  @override
  void render() => print('Render Android Material Button');
}

class _CupertinoButton implements PlatformButton {
  @override
  void render() => print('Render iOS Cupertino Button');
}

void testUsage() {
  // Luôn trả về cùng một instance (Singleton)
  final db1 = DatabaseClient();
  final db2 = DatabaseClient();
  assert(identical(db1, db2));

  // Trả về subclass tương ứng (Factory)
  final btn = PlatformButton('ios');
  btn.render();
}

