// 1. Domain Use-case thực thi đúng 1 trách nhiệm duy nhất (SRP)
class TransferFundsUseCase {
  final AccountRepository accountRepo;
  final TransactionLogRepository logRepo;

  TransferFundsUseCase({
    required this.accountRepo,
    required this.logRepo,
  });

  // Sử dụng cú pháp callable class 'call' trong Dart
  Future<String> call({
    required String senderId,
    required String receiverId,
    required double amount,
  }) async {
    // 🛡️ Kiểm tra các quy tắc nghiệp vụ cốt lõi
    if (amount <= 0) throw ArgumentError('Số tiền chuyển phải lớn hơn 0');
    if (senderId == receiverId) throw ArgumentError('Không thể tự chuyển cho chính mình');

    final senderAccount = await accountRepo.getById(senderId);
    if (senderAccount.balance < amount) {
      throw InsufficientBalanceException('Số dư tài khoản không đủ');
    }

    // Điều phối giao dịch qua các repository
    final transactionId = await accountRepo.executeTransfer(senderId, receiverId, amount);
    await logRepo.recordAuditLog(transactionId);

    return transactionId;
  }
}

class InsufficientBalanceException implements Exception {
  final String message;
  InsufficientBalanceException(this.message);
}

