class UserModel extends UserEntity {
  const UserModel({
    required super.id,
    required super.displayName,
    required super.isVerified,
  });

  // Chịu trách nhiệm tương thích với format snake_case của Backend
  factory UserModel.fromJson(Map<String, dynamic> json) {
    return UserModel(
      id: json['user_id'] as String,
      displayName: json['full_name'] as String,
      isVerified: (json['verified_status'] as int?) == 1,
    );
  }

  Map<String, dynamic> toJson() => {
    'user_id': id,
    'full_name': displayName,
    'verified_status': isVerified ? 1 : 0,
  };

  // Hàm mapping sạch sẽ sang Entity
  UserEntity toEntity() => UserEntity(id: id, displayName: displayName, isVerified: isVerified);
}

