void handlePushNotification(Map<String, dynamic> payload) {
  // ✅ Dart 3 Pattern Matching: Kiểm tra cấu trúc Map và unwrap dữ liệu an toàn
  switch (payload) {
    // Khớp khi có type == 'chat' VÀ sender là String VÀ unwrap message
    case {'type': 'chat', 'sender': String user, 'message': String text}:
      print('Tin nhắn từ $user: $text');

    // Khớp khi type == 'promo' kèm điều kiện guard clause (when)
    case {'type': 'promo', 'discount': int percent} when percent >= 50:
      print('Khuyến mãi khủng: Giảm $percent%!');

    // Khớp danh sách tọa độ GPS [lat, long]
    case {'location': [double lat, double long]}:
      print('Vị trí nhận được: Lat $lat, Long $long');

    case _:
      print('Thông báo không xác định hoặc payload không hợp lệ');
  }
}

// Ví dụ if-case tiện lợi cho unboxing
void displayUserRole(Object data) {
  if (data case {'role': 'admin', 'permissions': List<String> perms}) {
    print('Admin with ${perms.length} permissions');
  }
}

