import 'package:flutter/material.dart';

sealed class OrderStatus {}
class Pending extends OrderStatus {}
class Shipped extends OrderStatus { final String trackingCode; Shipped(this.trackingCode); }
class Cancelled extends OrderStatus { final String reason; Cancelled(this.reason); }

class OrderBadgeWidget extends StatelessWidget {
  final OrderStatus status;
  const OrderBadgeWidget({super.key, required this.status});

  @override
  Widget build(BuildContext context) {
    // ✅ SWITCH EXPRESSION: Trả về trực tiếp Widget ngay trong hàm build
    // Compiler ép buộc phải liệt kê đủ mọi trạng thái của sealed class (Exhaustive)
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
      child: switch (status) {
        Pending() => const Text('Đang xử lý...', style: TextStyle(color: Colors.orange)),
        Shipped(:final trackingCode) => Text('Đang giao: $trackingCode', style: const TextStyle(color: Colors.blue)),
        Cancelled(:final reason) => Text('Đã hủy ($reason)', style: const TextStyle(color: Colors.red)),
      },
    );
  }
}

