import 'package:dio/dio.dart';

class ApiClient {
  late final Dio _dio;
  final CancelToken _cancelToken = CancelToken();

  ApiClient() {
    _dio = Dio(BaseOptions(
      baseUrl: 'https://api.domain.com/v1',
      connectTimeout: const Duration(seconds: 10),
      receiveTimeout: const Duration(seconds: 10),
    ));

    // 🛡️ Đăng ký Interceptor xử lý Authentication tự động
    _dio.interceptors.add(InterceptorsWrapper(
      onRequest: (options, handler) {
        options.headers['Authorization'] = 'Bearer current_access_token_123';
        return handler.next(options); // Cho phép request đi tiếp
      },
      onError: (DioException error, handler) async {
        if (error.response?.statusCode == 401) {
          // Xử lý refresh token ngầm và retry request
          print('Token expired. Refreshing token in background...');
          // Sau khi refresh thành công -> return handler.resolve(await _dio.fetch(error.requestOptions));
        }
        return handler.next(error);
      },
    ));
  }

  // Hủy request ngay lập tức khi widget unmount
  void cancelActiveRequests() {
    _cancelToken.cancel('User navigated away from screen');
  }
}

