import 'package:firebase_auth/firebase_auth.dart';

class AuthService {
  final FirebaseAuth _auth = FirebaseAuth.instance;

  // ✅ Nguồn chân lý duy nhất: Stream phát ra User? khi trạng thái đổi
  Stream<User?> get authStateChanges => _auth.authStateChanges();

  Future<void> signInWithEmailPassword(String email, String password) async {
    try {
      await _auth.signInWithEmailAndPassword(
        email: email.trim(),
        password: password,
      );
    } on FirebaseAuthException catch (e) {
      // Xử lý chuẩn mã lỗi Firebase nghiệp vụ
      switch (e.code) {
        case 'user-not-found':
          throw Exception('Không tìm thấy tài khoản với email này.');
        case 'wrong-password':
        case 'invalid-credential':
          throw Exception('Mật khẩu không chính xác.');
        case 'user-disabled':
          throw Exception('Tài khoản này đã bị khóa.');
        default:
          throw Exception('Lỗi xác thực: ${e.message}');
      }
    }
  }
}

