import 'package:flutter/material.dart';

// 1. Định nghĩa InheritedWidget tùy chỉnh
class AppThemeScope extends InheritedWidget {
  final Color primaryColor;

  const AppThemeScope({
    super.key,
    required this.primaryColor,
    required super.child,
  });

  // Phương thức helper tĩnh với tra cứu O(1) và đăng ký phụ thuộc
  static AppThemeScope of(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<AppThemeScope>();
    assert(scope != null, 'No AppThemeScope found in context');
    return scope!;
  }

  // 🛡️ Kiểm tra xem dữ liệu có thực sự đổi để kích hoạt rebuild các widget con hay không
  @override
  bool updateShouldNotify(AppThemeScope oldWidget) {
    return primaryColor != oldWidget.primaryColor;
  }
}

// 2. Widget con tiêu thụ dữ liệu
