import 'package:flutter/material.dart';

class SafeAsyncView extends StatefulWidget {
  const SafeAsyncView({super.key});

  @override
  State<SafeAsyncView> createState() => _SafeAsyncViewState();
}

class _SafeAsyncViewState extends State<SafeAsyncView> {
  // 🛡️ BẮT BUỘC: Khởi tạo một lần, lưu giữ tham chiếu ổn định
  late final Future<String> _userFuture;

  @override
  void initState() {
    super.initState();
    _userFuture = _loadUserProfile();
  }

  Future<String> _loadUserProfile() async {
    await Future.delayed(const Duration(milliseconds: 500));
    return 'Alice Wonderland';
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<String>(
      future: _userFuture, // Truyền tham chiếu đã lưu, KHÔNG gọi hàm tại đây
      builder: (context, snapshot) {
        return switch (snapshot.connectionState) {
          ConnectionState.waiting => const CircularProgressIndicator(),
          ConnectionState.done when snapshot.hasError => Text('Lỗi: ${snapshot.error}'),
          ConnectionState.done when snapshot.hasData => Text('Xin chào, ${snapshot.data}'),
          _ => const SizedBox.shrink(),
        };
      },
    );
  }
}

