import 'package:flutter/services.dart';

class NativeBatteryService {
  // 1. Khai báo MethodChannel với định danh duy nhất
  static const MethodChannel _channel = MethodChannel('com.example.app/battery');

  Future<int> getBatteryLevel() async {
    try {
      // Gọi hàm native không đồng bộ
      final int? result = await _channel.invokeMethod<int>('getBatteryLevel');
      return result ?? 0;
    } on PlatformException catch (e) {
      print('Lỗi từ phía Native code: ${e.message}');
      return -1;
    }
  }

  // 2. EventChannel để stream dữ liệu cảm biến native liên tục
  static const EventChannel _sensorChannel = EventChannel('com.example.app/step_sensor');

  Stream<int> get stepCountStream {
    return _sensorChannel.receiveBroadcastStream().map((event) => event as int);
  }
}

