// Tooling automation script viết bằng Pure Dart cho CI/CD pipeline
// Chạy trong GitHub Actions: dart run tool/ci_verify.dart
void main() async {
  print('🚀 Starting Flutter CI Pipeline Verification...');

  final checks = [
    ('Analyze', ['flutter', 'analyze', '--fatal-infos']),
    ('Format Check', ['dart', 'format', '--output=none', '--set-exit-if-changed', '.']),
    ('Unit & Widget Tests', ['flutter', 'test', '--coverage']),
  ];

  for (final (name, cmd) in checks) {
    print('⏳ Running: $name...');
    final result = await Process.run(cmd.first, cmd.sublist(1));
    if (result.exitCode != 0) {
      stderr.writeln('❌ $name FAILED with exit code ${result.exitCode}:');
      stderr.writeln(result.stderr);
      exit(1);
    }
    print('✅ $name PASSED');
  }

  print('🎉 All CI Quality Gates Passed Successfully!');
}

