import 'package:flutter/material.dart';

// 1. Khai báo sealed class: Toàn bộ class con phải nằm trong cùng file này
sealed class PaymentResultState {}

class PaymentPending extends PaymentResultState {}
class PaymentSuccess extends PaymentResultState {
  final String transactionId;
  PaymentSuccess(this.transactionId);
}
class PaymentFailed extends PaymentResultState {
  final String errorMessage;
  PaymentFailed(this.errorMessage);
}

// 2. Tiêu thụ an toàn tuyệt đối với Switch Expression
Widget buildPaymentBadge(PaymentResultState state) {
  // ✅ Compiler ĐẢM BẢO BAO PHỦ: Không cần default case!
  // Nếu thêm class PaymentRefunded vào sealed class ở trên,
  // hàm này sẽ báo lỗi compile-time ngay lập tức, bắt buộc dev phải xử lý
  return switch (state) {
    PaymentPending() => const CircularProgressIndicator(),
    PaymentSuccess(:final transactionId) => Text('Thành công: #$transactionId'),
    PaymentFailed(:final errorMessage) => Text('Lỗi: $errorMessage', style: const TextStyle(color: Colors.red)),
  };
}

