import 'package:flutter_riverpod/flutter_riverpod.dart';

// 1. Compile-time safe: Không lo trùng kiểu, không sợ ProviderNotFoundException
final productDetailProvider = FutureProvider.autoDispose.family<String, String>((ref, productId) async {
  // 2. Quản trị bộ nhớ thông minh: Tự động hủy khi không còn ai xem
  final link = ref.keepAlive(); // Giữ cache

  // Thiết lập timer tự động giải phóng bộ nhớ sau 5 phút không hoạt động
  final timer = Stream.periodic(const Duration(minutes: 5)).listen((_) {
    link.close(); // Cho phép thu gom rác
  });
  ref.onDispose(() => timer.cancel());

  return 'Data for product $productId';
});

