import 'package:bloc_concurrency/bloc_concurrency.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

// 1. Events định danh rõ ràng mọi hành vi nghiệp vụ của người dùng
sealed class PaymentEvent {}
class SubmitPaymentRequested extends PaymentEvent {
  final double amount;
  SubmitPaymentRequested(this.amount);
}

// 2. States đại diện cho các trạng thái của Finite State Machine
sealed class PaymentState {}
class PaymentInitial extends PaymentState {}
class PaymentSubmitting extends PaymentState {}
class PaymentSuccess extends PaymentState {}

// 3. BLoC với cơ chế kiểm soát đồng thời cực mạnh mẽ
class PaymentBloc extends Bloc<PaymentEvent, PaymentState> {
  PaymentBloc() : super(PaymentInitial()) {
    // 🛡️ BẢO VỆ CHỐNG DOUBLE-CLICK: Sử dụng transformer droppable()
    // Nếu người dùng ấn nút thanh toán liên tục 5 lần,
    // các event sau sẽ bị HỦY HOÀN TOÀN cho tới khi request đầu tiên xong
    on<SubmitPaymentRequested>(
      (event, emit) async {
        emit(PaymentSubmitting());
        await Future.delayed(const Duration(seconds: 2)); // Xử lý thanh toán
        emit(PaymentSuccess());
      },
      transformer: droppable(), // Chặn double-submit giao dịch
    );
  }
}

