// Khai báo contract lưu trữ local
abstract class LocalCacheStorage {
  Future<List<String>> readCachedTodos();
  Future<void> writeCachedTodos(List<String> todos);
}

// Quản trị trạng thái Offline-first với AsyncNotifier trong Riverpod 2.x
class PersistentTodoListNotifier extends AsyncNotifier<List<String>> {
  late final LocalCacheStorage _storage;

  @override
  Future<List<String>> build() async {
    _storage = ref.watch(localCacheStorageProvider);

    // 1. Trả về dữ liệu Offline từ local cache ngay lập tức
    final localData = await _storage.readCachedTodos();

    // 2. Kích hoạt sync ngầm từ server mà không làm block UI render lần đầu
    _syncWithRemoteServer();

    return localData;
  }

  Future<void> addTodo(String task) async {
    final previousState = state.value ?? [];
    final updated = [...previousState, task];

    // 3. Optimistic Update: Cập nhật state UI và lưu local ngay lập tức
    state = AsyncData(updated);
    await _storage.writeCachedTodos(updated);

    try {
      // Gọi API server ngầm...
    } catch (e) {
      // Rollback nếu server từ chối
      state = AsyncData(previousState);
      await _storage.writeCachedTodos(previousState);
    }
  }

  void _syncWithRemoteServer() async {
    // Logic gọi API đồng bộ ngầm...
  }
}

final localCacheStorageProvider = Provider<LocalCacheStorage>((ref) => throw UnimplementedError());
final persistentTodoProvider = AsyncNotifierProvider<PersistentTodoListNotifier, List<String>>(
  PersistentTodoListNotifier.new,
);

