import 'package:shorebird_code_push/shorebird_code_push.dart';

class ShorebirdUpdateManager {
  final ShorebirdUpdater _updater = ShorebirdUpdater();

  // Kiểm tra và tải bản vá OTA ngầm trong ứng dụng
  Future<void> checkForHotfixPatch(BuildContext context) async {
    // Kiểm tra xem Shorebird có đang hoạt động trên thiết bị này không
    if (!_updater.isAvailable) return;

    final status = await _updater.checkForUpdate();

    if (status == UpdateStatus.outdated) {
      print('Phát hiện bản vá mới! Đang tải ngầm...');
      await _updater.update();

      if (!context.mounted) return;
      // Hiển thị thông báo nhẹ nhàng cho người dùng khởi động lại app
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: const Text('Bản cập nhật mới đã sẵn sàng!'),
          action: SnackBarAction(
            label: 'Khởi động lại',
            onPressed: () {
              // App sẽ áp dụng mã Dart mới ngay trong lần khởi động tiếp theo
            },
          ),
        ),
      );
    }
  }
}

