import 'package:flutter/material.dart';

class ExplicitPulseAnimationScreen extends StatefulWidget {
  const ExplicitPulseAnimationScreen({super.key});

  @override
  State<ExplicitPulseAnimationScreen> createState() => _ExplicitPulseAnimationScreenState();
}

class _ExplicitPulseAnimationScreenState extends State<ExplicitPulseAnimationScreen>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    // Khởi tạo AnimationController tường minh
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    )..repeat(reverse: true); // Lặp đi lặp lại vô tận

    // Ánh xạ controller (0.0 -> 1.0) sang giá trị scale (1.0 -> 1.3)
    _scaleAnimation = Tween<double>(begin: 1.0, end: 1.3).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _controller.dispose(); // Bắt buộc giải phóng ticker
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Center(
      // ✅ TỐI ƯU: AnimatedBuilder chỉ rebuild Transform, StaticLogo không bị build lại!
      child: AnimatedBuilder(
        animation: _scaleAnimation,
        builder: (context, child) {
          return Transform.scale(
            scale: _scaleAnimation.value,
            child: child,
          );
        },
        child: const FlutterLogo(size: 100), // Widget tĩnh truyền qua child
      ),
    );
  }
}

