import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';

class GestureConflictResolverScreen extends StatelessWidget {
  const GestureConflictResolverScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Center(
        // Giải quyết xung đột cử chỉ bằng RawGestureDetector và EagerGestureRecognizer
        child: RawGestureDetector(
          gestures: <Type, GestureRecognizerFactory>{
            // Ép buộc recognizer này luôn thắng ngay lập tức trong Gesture Arena
            // Bỏ qua các sự kiện cạnh tranh từ widget cha
            EagerGestureRecognizer: GestureRecognizerFactoryWithHandlers<EagerGestureRecognizer>(
              () => EagerGestureRecognizer(),
              (EagerGestureRecognizer instance) {
                instance.onDown = (details) => print('Eager win: Touch confirmed');
              },
            ),
          },
          child: Container(
            width: 200,
            height: 200,
            color: Colors.blue,
            child: const Center(child: Text('Dominant Touch Box')),
          ),
        ),
      ),
    );
  }
}

